from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class BlockCellV1(SchemaObject):
    detailed_statuses = SchemaField(name='detailedStatuses', many=True)
    error_code = SchemaField(name='errorCode', many=True)
    error_message = SchemaField(name='errorMessage')
    id = SchemaField(name='id', not_null=True)
    status = SchemaField(name='status', not_null=True)

    def __init__(self, detailed_statuses, error_code, error_message, id, status):
        self.detailed_statuses = detailed_statuses
        self.error_code = error_code
        self.error_message = error_message
        self.id = id
        self.status = status
        super(BlockCellV1, self).__init__()
